\label{hyp:f}
The function $f$ satisfies
\begin{equation}\label{eq:kpp}
 f\in C^2([0,1]),\quad f(0)=f(1)=0,\quad
 f'(0)=1,\quad f'(1)<0,\quad 0<f(s)\le s\quad(0<s<1).
\end{equation}

\label{hyp:data}
The initial function $u_0$ is measurable, and there exist $a<b<0$ such that
\begin{equation}\label{eq:data}
 0\le u_0\le1,\qquad u_0(x)=1\quad(x\le a),\qquad
 u_0(x)=0\quad(x\ge b).
\end{equation}

\label{thm:phase}
Suppose that Assumptions~\ref{hyp:f}--\ref{hyp:data} hold. For every $\beta\in[0,\infty)$, there is a unique $\xi_\beta\in\mathbb R$ such that, as $t\to\infty$,
\begin{equation}\label{eq:phase-limit}
 \sup_{x\ge0}\big|u^\beta(t,x)-U_*(x-m(t)-\xi_\beta)\big|\longrightarrow0.
\end{equation}
At $x=0$, the value of $u^\beta$ in~\eqref{eq:phase-limit} is understood as the right-hand trace $u^\beta(t,0^+)$. Define the leading-edge amplitude by $\alpha_\beta=A_*e^{\xi_\beta}>0$. For every $\eta\in(0,1)$, the following limit exists, is finite, and is independent of $\eta$:
\begin{equation}\label{eq:delay}
 \tau_\beta:=\lim_{R\to\infty}
 \big(T_\eta^\beta(R)-T_\eta^0(R)\big)
 =\frac{\xi_0-\xi_\beta}{2}
 =\frac12\log\frac{\alpha_0}{\alpha_\beta}.
\end{equation}
The maps $\beta\mapsto\alpha_\beta$ and $\beta\mapsto\tau_\beta$ are continuous on $[0,\infty)$, and $\tau_0=0$.

\label{thm:monotonicity}
Suppose that Assumptions~\ref{hyp:f}--\ref{hyp:concave} hold. The leading-edge amplitude is strictly decreasing in the resistance, whereas the far-field delay is strictly increasing. More precisely,
\begin{equation}\label{eq:strict-order}
 0\le\beta_1<\beta_2<\infty
 \quad\Longrightarrow\quad
 \alpha_{\beta_1}>\alpha_{\beta_2},\qquad
 \tau_{\beta_1}<\tau_{\beta_2}.
\end{equation}
Since $\tau_0=0$, it follows that $\tau_\beta>0$ for every $\beta>0$.

\label{thm:small-beta}
Suppose that Assumptions~\ref{hyp:f}--\ref{hyp:concave} hold. The far-field delay is right differentiable at zero resistance and satisfies
\begin{equation}\label{eq:small-delay}
 \tau_\beta=K\beta+o(\beta)\qquad(\beta\downarrow0),\qquad
 K=\tau'_+(0)>\frac14.
\end{equation}
The leading-edge amplitude also has a right derivative at zero, and
\[
 \dot\alpha_0:=\lim_{\beta\downarrow0}
 \frac{\alpha_\beta-\alpha_0}{\beta},\qquad
 K=-\frac{\dot\alpha_0}{2\alpha_0}.
\]
The right first variation
\[
 w=\left.\partial_\beta u^\beta\right|_{\beta=0^+}
   =\lim_{\beta\downarrow0}\frac{u^\beta-u^0}{\beta}
\]
exists, with convergence uniform on each finite time interval in $L^\infty(\mathbb R\setminus\{0\})$, and satisfies
\begin{equation}\label{eq:first-variation-main}
 \begin{cases}
 w_t=w_{xx}+f'(u^0)w,&t>0,\quad x\ne0,\\
 [w](t)=u_x^0(t,0),&t>0,\\
 [w_x](t)=0,&t>0,\\
 w(0,x)=0,&x\ne0.
 \end{cases}
\end{equation}
The amplitude derivative is recovered from the leading edge of this first variation: for every $0<\theta<1/3$,
\begin{equation}\label{eq:alpha-derivative-main}
 \dot\alpha_0=\lim_{t\to\infty}
 \frac{e^{t^\theta}w(t,m(t)+t^\theta)}{t^\theta}.
\end{equation}

\label{thm:large-beta}
Suppose that Assumptions~\ref{hyp:f}--\ref{hyp:data} hold. As $\beta\to\infty$, the leading-edge amplitude satisfies
\begin{equation}\label{eq:large-amplitude}
 \alpha_\beta=\frac{I}{\sqrt\pi}\frac{\log\beta}{\beta}(1+o(1)).
\end{equation}
Consequently, the far-field delay satisfies
\begin{equation}\label{eq:large-delay}
 \tau_\beta=\frac12\log\beta-\frac12\log\log\beta
 +\frac12\log\frac{\sqrt\pi\alpha_0}{I}+o(1).
\end{equation}

\label{prop:well-posedness}
Under Assumption~\ref{hyp:f}, let $u_0$ be measurable with $0\le u_0\le1$, and fix $0\le\beta<\infty$. There is a unique global bounded mild solution $u^\beta$, characterized by
\begin{equation}\label{eq:mild}
 u^\beta(t,x)=\int_\mathbb R P_\beta(t,x,y)u_0(y)\,dy
 +\int_0^t\int_\mathbb R P_\beta(t-s,x,y)f(u^\beta(s,y))\,dy\,ds.
\end{equation}
It satisfies $0\le u^\beta\le1$ and is classical on each side for $t>0$, with one-sided traces satisfying \eqref{eq:interface}. At $\beta=0$, it is the classical homogeneous full-line solution for positive times. As $t\downarrow0$, $u^\beta(t,\cdot)\to u_0$ locally in $L^p(\mathbb R)$ for every $1\le p<\infty$, and pointwise at every continuity point of $u_0$ away from the interface.

For the same fixed $\beta$ and reaction $f$, comparison holds for any two measurable initial data taking values in $[0,1]$: if $u_0\le v_0$ almost everywhere, then their solutions satisfy $u^\beta(t,x)\le v^\beta(t,x)$ for $t>0$, including the corresponding one-sided interface traces.

\label{lem:reflection-comparison}
Under Assumptions~\ref{hyp:f}--\ref{hyp:data}, fix $0\le\beta<\infty$. Then $p_\beta(t,x)>q_\beta(t,x)$ for $t>0$ and $x>0$. For $\beta>0$, this inequality also holds at $x=0$, and
\begin{equation}\label{eq:reflection}
 j_\beta(t):=-q_{\beta,x}(t,0)
 =\frac{p_\beta(t,0)-q_\beta(t,0)}\beta>0,
 \qquad t>0.
\end{equation}
Here $j_\beta$ is oriented from the donor side to the receiving side, so $[u^\beta](t)=-\beta j_\beta(t)$ for $\beta>0$. For $\beta=0$, the interface flux satisfies $j_0(t):=-u_x^0(t,0)>0$. Moreover, for every finite $\beta\ge0$,
\begin{equation}\label{eq:right-monotone}
 q_{\beta,x}(t,x)<0\qquad(t>0,x>0).
\end{equation}

\label{lem:leading-edge}
Under Assumptions~\ref{hyp:f}--\ref{hyp:data}, for every finite $\beta\ge0$ there exists a leading-edge coefficient $\alpha_\beta>0$, independent of the auxiliary cutoff exponent $\rho$. Section~\ref{sec:phase} identifies it with $A_*e^{\xi_\beta}$ in Theorem~\ref{thm:phase}.
Fix $0<\rho<1/3$. There are constants $C,T$, depending on $f,u_0,\rho$ but independent of $\beta$, such that $0<\alpha_\beta\le C$ and, for $t\ge T$,
\begin{equation}\label{front:nonlinear-profile}
 \left|w_\beta(\log t,\eta)-\alpha_\beta\eta e^{-\eta^2/4}\right|
       \le Ct^{\rho-1/2}e^{-\eta^2/7},
       \qquad\eta\ge t^{\rho-1/2}.
\end{equation}
In particular, locally uniformly for $\eta\in(0,\infty)$,
\[
 t^{-1/2}e^{\sqrt t\eta}
 u^\beta(t,m(t)+\sqrt t\eta)
       \longrightarrow\alpha_\beta\eta e^{-\eta^2/4}.
\]
If $0<\gamma<1/3$, then
\begin{equation}\label{front:intermediate}
 \frac{e^{t^\gamma}u^\beta(t,m(t)+t^\gamma)}{t^\gamma}
       \longrightarrow\alpha_\beta,
 \qquad
 \frac{e^{t^\gamma}u_x^\beta(t,m(t)+t^\gamma)}{t^\gamma}
       \longrightarrow-\alpha_\beta.
\end{equation}
Moreover, with $\ell(t)=m(t)+t^\rho$,
\begin{equation}\label{front:uniform-moment}
 \mathcal J_\beta(t):=e^{-2t}\int_{\ell(t)}^\infty
 (x-\ell(t))e^xu^\beta(t,x)\,dx,
 \qquad
 |\mathcal J_\beta(t)-2\sqrt\pi\alpha_\beta|
       \le Ct^{\rho-1/2}.
\end{equation}

\label{matching:energy-lemma}
Suppose that Assumption~\ref{hyp:f} holds. Given $\alpha>0$ and $T\ge1$, let $h\in C^1([T,\infty))$ satisfy
$0\le h\le1$ and $\sup_{t\ge T}|h'(t)|<\infty$.
Let $q_T$ be a measurable function on $(-R(T),R(T))$ with $0\le q_T\le1$. On $-R(t)<z<R(t)$, let $q_{\mathrm{aux}}$ be the bounded solution of
\begin{equation}\label{matching:auxiliary-equation}
 \begin{cases}
 (q_{\mathrm{aux}})_t=(q_{\mathrm{aux}})_{zz}
  +\left(2-\dfrac3{2t}\right)(q_{\mathrm{aux}})_z
  +f(q_{\mathrm{aux}}),\\[1mm]
 q_{\mathrm{aux}}(t,-R(t))=h(t),\\
 q_{\mathrm{aux}}(t,R(t))=\alpha R(t)e^{-R(t)},\\
 q_{\mathrm{aux}}(T,z)=q_T(z).
 \end{cases}
\end{equation}
The equation and boundary conditions hold for $t>T$. The solution is understood in the mild sense, is classical in the interior for $t>T$, and attains the lateral boundary data continuously away from the initial corners. Its initial trace is $q_T$ locally in $L^p((-R(T),R(T)))$ for $1\le p<\infty$; no compatibility at the initial corners is required. Assume that $T$ is large enough that $\alpha R(t)e^{-R(t)}\le1$ for all $t\ge T$. Then, for every $0<K<\infty$,
\begin{equation}\label{matching:auxiliary-limit}
 \lim_{t\to\infty}\sup_{|z|\le K}
 \left|q_{\mathrm{aux}}(t,z)
 -U_*\!\left(z-\log\frac\alpha{A_*}\right)\right|=0.
\end{equation}

\label{prop:pointwise-order}
Under Assumptions~\ref{hyp:f}--\ref{hyp:concave}, solutions with the same initial datum satisfy
\begin{equation}
 q_{\beta_1}(t,x)>q_{\beta_2}(t,x)
 \qquad(t>0,\ x>0),\qquad 0\le\beta_1<\beta_2<\infty.
 \label{order:pointwise}
\end{equation}

First suppose $0<\beta_1<\beta_2$ and put $k_i=2/\beta_i$, so $k_1>k_2$.
Use the subscript $i$ for the reflected quantities in~\eqref{eq:fold}.
Lemma~\ref{lem:reflection-comparison} gives
\begin{equation}
 D_i(t,x)>0\qquad(t>0,\ x\ge0).
 \label{order:D-positive}
\end{equation}
Set
\begin{equation}
 r=S_1-S_2,\qquad h=D_2-D_1.
 \label{order:rh}
\end{equation}
Both states and the line segment joining them lie in the convex set
$\{(S,D):0\le S-D\le S+D\le1\}$. On this set concavity gives
\begin{equation}
 F_S=H_D=\frac{f'(S+D)+f'(S-D)}2,\qquad
 F_D=H_S=\frac{f'(S+D)-f'(S-D)}2\le0.
 \label{order:jacobian}
\end{equation}
At each $(t,x)$, write
$(S_\theta,D_\theta)=(1-\theta)(S_2,D_2)+\theta(S_1,D_1)$ and define
\[
 A=\int_0^1 F_S(S_\theta,D_\theta)\,d\theta,
 \qquad B=-\int_0^1 F_D(S_\theta,D_\theta)\,d\theta.
\]
These coefficients are bounded and $B\ge0$. The identities in
\eqref{order:jacobian} give the cooperative system
\begin{equation}
 \begin{cases}
 r_t=r_{xx}+Ar+Bh,\\
 h_t=h_{xx}+Br+Ah.
 \end{cases}
 \label{order:cooperative}
\end{equation}
The common initial datum gives zero initial data for $(r,h)$, and the boundary conditions are
\begin{equation}
 r_x(t,0)=0,\qquad
 -h_x(t,0)+k_2h(t,0)=(k_1-k_2)D_1(t,0)>0.
 \label{order:rh-bc}
\end{equation}
For the cooperative comparison, choose $L\ge\|A\|_\infty$ and use the
damped scalar Neumann and Robin semigroups. Both preserve positivity;
the nonnegative Robin boundary input also has a nonnegative response by
scalar comparison. In the Duhamel system the remaining coefficients are
$A+L\ge0$ and $B\ge0$, so successive approximation preserves
nonnegativity and gives $r,h\ge0$. This mild argument applies to the
measurable initial datum without initial compatibility conditions.
For positive times, $h_t-h_{xx}-Ah=Br\ge0$.
The strictly positive boundary input in~\eqref{order:rh-bc} excludes an
identically zero solution on any positive time interval. The strong maximum
principle therefore gives $h(t,x)>0$ for $t>0,x>0$.
Since $q_{\beta_1}-q_{\beta_2}=r+h$, this proves~\eqref{order:pointwise}
when $\beta_1>0$. Strict concavity is not needed: strictness comes from the
boundary input, even if the coupling coefficient $B$ vanishes.

If $\beta_1=0$, use $r=S_0-S_2$ and $h=D_2-D_0$.
The same coefficient construction gives~\eqref{order:cooperative}.
Here $D_0(t,0)=0$ and $D_0>0$ in the interior by
Lemma~\ref{lem:reflection-comparison}; the Hopf lemma gives
$(D_0)_x(t,0)>0$. Thus the boundary condition for $h$ becomes
\begin{equation}
 -h_x(t,0)+k_2h(t,0)=(D_0)_x(t,0)>0.
 \label{order:zero-rh-bc}
\end{equation}
The same mild comparison and positive-time strong maximum principle give
$r\ge0$ and $h>0$, completing the proof.

\label{lem:positive-tail}
Let $W(t,x)>0$ be a classical solution for $t>0,x>0$, bounded on
$[t_0,T_1]\times(0,\infty)$ for every $0<t_0<T_1<\infty$, and satisfying
\begin{equation}
 W_t=W_{xx}+c(t,x)W,
 \label{order:W-pde}
\end{equation}
where $c$ is bounded. Let $m$ be the reference position defined in~\eqref{eq:m}.
Assume that, for all sufficiently large $t$ and all $z\geq0$,
\begin{equation}
 c(t,m(t)+z)\geq1-Ct e^{-z}.
 \label{order:potential-tail}
\end{equation}
Then, for every $0<\gamma<1/3$,
\begin{equation}
 \liminf_{t\to\infty}
 \frac{e^{t^\gamma}W(t,m(t)+t^\gamma)}{t^\gamma}>0.
 \label{order:positive-amplitude}
\end{equation}
The positive lower bound may depend on $W$, $\gamma$, and the coefficient
bounds and starting time in~\eqref{order:potential-tail}; no uniform lower
bound over a family of positive solutions is asserted. No initial trace at
$t=0$ or boundary condition at $x=0$ is required.

Fix $0<\gamma<1/3$, choose $0<\kappa<\gamma$, and set
\begin{equation}
 B(t)=t^\kappa,\qquad
 P(t,z)=t^{-3/2}e^zW(t,m(t)+z),\qquad
 \widetilde P(t,y)=P(t,B(t)+y).
 \label{order:W-transform}
\end{equation}
A direct calculation gives
\begin{equation}
 \widetilde P_t=\widetilde P_{yy}+b(t)\widetilde P_y
 +(c(t,m(t)+B(t)+y)-1)\widetilde P,
 \qquad b(t)=B'(t)-\frac3{2t}.
 \label{order:W-transformed-pde}
\end{equation}
For all sufficiently large $t$ and $y>0$, the potential is bounded below by
$-\omega(t)$, where
\begin{equation}
 \omega(t)=Ct e^{-t^\kappa}.
 \label{order:omega}
\end{equation}
This function is integrable at infinity.

Choose $T>1$ sufficiently large that $m(t)+B(t)>0$, the potential bound
\eqref{order:potential-tail} holds, $b(t)\ge0$, and
$0<t^{\kappa-1/2}\le1/2$ for every $t\ge T$. Fix this $T$ before choosing
the initial seed and the normalization below.
We construct a subsolution from the Dirichlet heat profile
$yr^{-3/2}e^{-y^2/(4r)}$. The exponential factor $e^{-b(t)y/2}$ removes
the first spatial derivative from the residual. Slowing the heat time
slightly below unit speed creates a negative quadratic term that absorbs
the term involving $b'(t)y$. Accordingly, define
\begin{equation}
 \varepsilon(t)=t^{\kappa-1/2},\qquad
 r(T)=1,\qquad r'(t)=1-\varepsilon(t).
 \label{order:time-change}
\end{equation}
Then $r>0$ and $r(t)/t\to1$. Define
\begin{equation}
 Q(t,y)=a(t)e^{-b(t)y/2}
 y\,r(t)^{-3/2}\exp\left(-\frac{y^2}{4r(t)}\right),
 \label{order:subsolution}
\end{equation}
The normalization $a(T)>0$ will be chosen from an initial Gaussian lower bound for $W$. For now, prescribe
\begin{equation}
 \frac{a'(t)}{a(t)}=-\left[
 \omega(t)+\frac{b(t)^2}{4}
 +\frac{3\varepsilon(t)}{2r(t)}
 +\frac{r(t)^2b'(t)^2}{4\varepsilon(t)}\right].
 \label{order:a-choice}
\end{equation}
Substitution gives the exact identity
\begin{equation}
 \frac{Q_t-Q_{yy}-bQ_y+\omega Q}{Q}
 =-\left(\frac{\sqrt\varepsilon\,y}{2r}
 +\frac{rb'}{2\sqrt\varepsilon}\right)^2\leq0.
 \label{order:subsolution-residual}
\end{equation}
Since
\begin{equation}
 b(t)^2=O(t^{2\kappa-2}),\qquad
 \frac{\varepsilon(t)}{r(t)}
 +\frac{r(t)^2b'(t)^2}{\varepsilon(t)}
 =O(t^{\kappa-3/2}),
 \label{order:integrable-losses}
\end{equation}
and $2\kappa-2<-1$, $\kappa-3/2<-1$, all terms in~\eqref{order:a-choice}
are integrable on $[T,\infty)$. Thus, for any $a(T)>0$, the limit
$a_\infty$ equals $a(T)$ times the exponential of minus the finite integral
of the nonnegative loss terms, and is strictly positive.

To establish the initial comparison, fix $x_0=m(T)+B(T)>0$.
Positivity and continuity of $W(T-1,\cdot)$ allow us to choose a nonzero,
nonnegative smooth seed supported in $(x_0+1,x_0+2)$ and lying below
$W(T-1,\cdot)$.
Evolve this seed on the fixed half-line $x>x_0$ under the heat equation
with potential $-\|c\|_\infty$ and zero boundary data.
The comparison principle and the explicit Dirichlet kernel give
\begin{equation}
 W(T,x_0+y)\geq C_Ty e^{-y^2/4}\qquad(y>0).
 \label{order:initial-lower}
\end{equation}
Indeed, for $1\leq s\leq2$,
\begin{equation}
 G_1(y-s)-G_1(y+s)
 =\frac{2}{\sqrt{4\pi}}e^{-(y^2+s^2)/4}\sinh\frac{ys}{2}
 \geq c\,y e^{-y^2/4}.
 \label{order:dirichlet-seed-kernel}
\end{equation}
By~\eqref{order:initial-lower},
$\widetilde P(T,y)\geq C'_Ty e^{-y^2/4+y}$.
Since $r(T)=1$ and $b(T)\ge0$, choosing $0<a(T)\le C'_T$ ensures
$Q(T,y)\le\widetilde P(T,y)$ for all $y>0$. This fixes $a$ and its positive
limit $a_\infty$.

To justify comparison on the unbounded moving domain, return to the original variables and set
\[
 \underline W(t,x)=t^{3/2}e^{-(x-m(t))}
 Q\bigl(t,x-m(t)-B(t)\bigr),\qquad x>m(t)+B(t).
\]
By~\eqref{order:potential-tail} and~\eqref{order:subsolution-residual},
$\underline W_t-\underline W_{xx}-c\underline W\le0$.
The initial inequality holds by the choice of $a(T)$, and
$\underline W(t,m(t)+B(t))=0<W(t,m(t)+B(t))$.
The moving boundary is smooth and stays in $x>0$. Moreover, $b\ge0$ and
the Gaussian factor in $Q$ ensure that $\underline W$ is bounded on every
strip $T\le t\le T_1<\infty$, as is $W$ by assumption.
The comparison principle for bounded solutions on this moving half-line
therefore gives $\underline W\le W$, equivalently $Q\le\widetilde P$.
No boundary condition at spatial infinity is required in this bounded class.

Finally, set $y=t^\gamma-t^\kappa$. Since $\kappa<\gamma<1/3$,
\begin{equation}
 \frac{y}{t^\gamma}\to1,\qquad b(t)y\to0,\qquad
 \frac{y^2}{r(t)}\to0,\qquad \frac{r(t)}t\to1.
 \label{order:matching-limits}
\end{equation}
Equations~\eqref{order:subsolution} and~\eqref{order:W-transform} yield
\[
 \liminf_{t\to\infty}
 \frac{e^{t^\gamma}W(t,m(t)+t^\gamma)}{t^\gamma}
 \geq a_\infty>0.
\]

Fix $0\le\beta_1<\beta_2<\infty$ and set $W=q_{\beta_1}-q_{\beta_2}$.
Proposition~\ref{prop:pointwise-order} gives $0<W\le1$ on $t>0,x>0$.
Positive-time interior regularity makes $W$ a classical solution of
\begin{equation}
 W_t=W_{xx}+c(t,x)W,
 \qquad
 c(t,x)=\int_0^1f'\bigl(q_{\beta_2}(t,x)+\theta W(t,x)\bigr)\,d\theta.
 \label{order:difference-equation}
\end{equation}
The arguments of $f'$ lie in $[0,1]$, so $|c|\le\|f'\|_{L^\infty([0,1])}$.
Moreover, $f'(0)=1$ and $f\in C^2([0,1])$ imply
\[
 |f'(s)-1|\le\|f''\|_{L^\infty([0,1])}s,\qquad 0\le s\le1.
\]
Together with~\eqref{eq:uniform-leading-bound}, this gives, for all sufficiently
large $t$ and all $z\ge0$,
\begin{equation}
 q_{\beta_i}(t,m(t)+z)\leq Ct e^{-z},\qquad
 c(t,m(t)+z)\geq1-Ct e^{-z}.
 \label{order:difference-potential}
\end{equation}
All hypotheses of Lemma~\ref{lem:positive-tail} are therefore satisfied.
Here concavity enters only through the pointwise comparison giving $W>0$.
Fix any $0<\gamma<1/3$. Combining the positive lower bound with the amplitude
limits in Lemma~\ref{lem:leading-edge}, we obtain
\begin{equation}
 \alpha_{\beta_1}-\alpha_{\beta_2}
 =\lim_{t\to\infty}
 \frac{e^{t^\gamma}
 \bigl(q_{\beta_1}-q_{\beta_2}\bigr)(t,m(t)+t^\gamma)}{t^\gamma}
 >0.
 \label{order:strict-alpha}
\end{equation}
The phase formula $\xi_\beta=\log(\alpha_\beta/A_*)$ now gives
\begin{equation}\label{order:strict-phase}
 \xi_{\beta_1}-\xi_{\beta_2}
 =\log\frac{\alpha_{\beta_1}}{\alpha_{\beta_2}}>0.
\end{equation}
Thus the phase is strictly decreasing with resistance, and
\eqref{order:tau-alpha} yields
\begin{equation}
 \tau_{\beta_2}-\tau_{\beta_1}
 =\frac12\log\frac{\alpha_{\beta_1}}{\alpha_{\beta_2}}>0
 \qquad(0\leq\beta_1<\beta_2<\infty).
 \label{order:strict-tau}
\end{equation}
Taking $\beta_1=0$ and using $\tau_0=0$ gives $\tau_\beta>0$ for every $\beta>0$.

\label{small:finite-variation}
Under Assumptions~\ref{hyp:f}--\ref{hyp:data}, there exists a unique first variation $w$, bounded on $[0,T]\times(\mathbb R\setminus\{0\})$ for every $T>0$, such that
\begin{equation}\label{small:finite-expansion}
 \sup_{0\le t\le T}\|u^\beta(t,\cdot)-U(t,\cdot)-\beta w(t,\cdot)\|_{L^\infty(\mathbb R\setminus\{0\})}=o(\beta)
 \qquad(\beta\downarrow0).
\end{equation}
The function $w$ is classical in the interior of each half-line for positive times, has one-sided traces of $w$ and $w_x$ at the interface, and satisfies
\begin{equation}\label{small:variation-problem}
 \begin{cases}
 w_t=w_{xx}+f'(U)w,&x\ne0,\ t>0,\\
 [w](t)=U_x(t,0),&t>0,\\
 [w_x](t)=0,&t>0,\\
 w(0,x)=0,&x\ne0.
 \end{cases}
\end{equation}
The initial condition is attained in $L^\infty(\mathbb R\setminus\{0\})$ as $t\downarrow0$. This problem uniquely characterizes $w$ in the stated bounded solution class.

\label{small:uniform-flux}
Under Assumptions~\ref{hyp:f}--\ref{hyp:concave}, $d_\beta\in C^1((0,\infty))$
for each $\beta>0$. For any fixed $\beta_*>0$, there exist $T,C,\omega>0$,
depending on $f,u_0,\beta_*$ but independent of $\beta\in(0,\beta_*]$, such that
\begin{equation}\label{small:flux-decay}
 |d_\beta(t)|+|d'_\beta(t)|\le Ce^{-\omega t},\qquad t\ge T.
\end{equation}

\label{small:scaled-moment}
Under Assumptions~\ref{hyp:f}--\ref{hyp:concave}, fix $\beta_*>0$ and
$0<\rho<1/3$, and use $\mathcal J_\beta$ from~\eqref{front:uniform-moment}
with $\ell(t)=m(t)+t^\rho$.
There are constants $C,T$, depending on $f,u_0,\beta_*,\rho$ but not on
$0<\beta\le\beta_*$, such that, for $t\ge T$,
\begin{equation}\label{small:moment-uniform-error}
 \left|\frac{\mathcal J_\beta(t)-\mathcal J_0(t)}\beta
 -2\sqrt\pi\frac{\alpha_\beta-\alpha_0}\beta\right|
 \le Ct^{\rho-1/2}.
\end{equation}

\label{small:amplitude-derivative}
Under Assumptions~\ref{hyp:f}--\ref{hyp:concave}, the right derivative
$\dot\alpha_0$ of $\alpha_\beta$ at zero exists and is finite.
For every $0<\theta<1/3$,
\begin{equation}\label{small:response-amplitude}
 \dot\alpha_0=\lim_{t\to\infty}
 \frac{e^{t^\theta}w(t,m(t)+t^\theta)}{t^\theta}.
\end{equation}
Consequently,
\begin{equation}\label{small:delay-expansion}
 \tau_\beta=K\beta+o(\beta)\qquad(\beta\downarrow0),\qquad K=-\frac{\dot\alpha_0}{2\alpha_0}.
\end{equation}

\label{small:strict-coefficient}
Under Assumptions~\ref{hyp:f}--\ref{hyp:concave}, let $Z$ be the unique
solution, bounded on every finite time strip, of
\begin{equation}\label{small:positive-correction}
 \begin{cases}
 Z_t=Z_{xx}+f'(U)Z,&x>0,\\
 Z(t,0)=R(t,0),&t>0,\\
 Z(0,x)=0,&x>0.
 \end{cases}
\end{equation}
Here the equation holds classically in the interior for positive times,
the boundary condition holds by continuity, and the initial condition is
attained uniformly. Then, for every $0<\theta<1/3$, the limit
\begin{equation}\label{small:zeta-definition}
 \zeta=\lim_{t\to\infty}\frac{e^{t^\theta}Z(t,m(t)+t^\theta)}{t^\theta}
\end{equation}
exists, is independent of $\theta$, is strictly positive, and satisfies
\begin{equation}\label{small:coefficient-formula}
 \dot\alpha_0=-\frac{\alpha_0}{2}-\zeta,
 \qquad K=\frac14+\frac{\zeta}{2\alpha_0}>\frac14.
\end{equation}

\label{large:fixed-time-input}
Under Assumptions~\ref{hyp:f}--\ref{hyp:data}, define
\[
 v(t,x)=2\int_0^t e^{t-s}G_{t-s}(x)h(s)\,ds,\qquad v(0,x)=0.
\]
For every fixed $T>0$, there is $C_T$, depending only on $f,u_0,T$,
such that, for $0<\varepsilon\le1$ and $\beta=\varepsilon^{-1}$,
\begin{equation}\label{large:finite-time}
 \sup_{0\le t\le T}
 \left(\|p_N(t)-p_\beta(t)\|_\infty+\|q_\beta(t)\|_\infty\right)
 \le C_T\varepsilon,
\end{equation}
\begin{equation}\label{large:linear-input-error}
 \sup_{0\le t\le T}
 \left(\left|\frac{j_\beta(t)}\varepsilon-h(t)\right|
 +\left\|\frac{q_\beta(t)}\varepsilon-v(t)\right\|_\infty\right)
 \le C_T\varepsilon.
\end{equation}
Here $\|\cdot\|_\infty$ denotes the $L^\infty(0,\infty)$ norm.
At positive times we use the continuous representatives, so the bounds
also hold for the boundary traces. The flux is extended to $t=0$ by
$j_\beta(0)=0$.
In particular,
\begin{equation}\label{large:seed}
 \varepsilon^{-1}q_\beta(T,\cdot)\longrightarrow
 v_T:=v(T,\cdot)
 \qquad\text{uniformly on }[0,\infty).
\end{equation}
The profile $v_T$ is continuous and strictly positive on $[0,\infty)$.
After even extension to $\mathbb R$, it has the exponential moment
\begin{equation}\label{large:seed-mass}
 e^{-2T}\int_\mathbb R e^xv_T(x)\,dx
 =2\int_0^T e^{-2s}h(s)\,ds=:2I_T.
\end{equation}
